const fs = require('fs-extra');
const path = require('path');

const outputFileName = "TangSengFacade.lua"


function buildContent(config) {
    var content = ""
    content += `local module = {}\n\n`;
    content += `module.__Services = nil\n\n`;
    for (var path in config) {
        var item = config[path]
        if (item.UseDirectContent) {
            continue
        }
        var service = item.Key
        if (item.Key == undefined || item.Key == "") {
            throw new Error(path + " 服务名不能为空")
        }
        content += `function module.get${service}(): ${service}\n`;
        content += `    return module.__Services:GetService("${service}")\n`;
        content += `end\n\n`;
    }
    content += "return module\n"
    return content
}

function gen(config, outputPath) {
    fs.ensureDirSync(outputPath);
    var content = buildContent(config)
    fs.writeFileSync(path.join(outputPath, outputFileName), content);
    console.log(`write file ${path.join(outputPath, outputFileName)}`)
}


module.exports = gen;